{-| @Backend.Runtime.Kernel.Swiss — the flat table over two stores, as `Pudu.Eval.SwissTable`
    answers it. -}
module Pudu.Backend.Runtime.Kernel.Swiss (swissKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
swissKernelParts :: [(Text, [Text], [Text])]
swissKernelParts =
  [ ("swiss_hash", [],
      [ "static inline uint64_t pudu_swiss_hash(uint64_t word) {"
      , "  word = (word ^ (word >> 30)) * UINT64_C(0xBF58476D1CE4E5B9);"
      , "  word = (word ^ (word >> 27)) * UINT64_C(0x94D049BB133111EB);"
      , "  return word ^ (word >> 31);"
      , "}"
      ])
  , ("swiss_capacity", ["make"],
      [ "/* Sixteen slots at least, then the next power of two. */"
      , "static pudu_int pudu_swiss_capacity(pudu_int wanted) {"
      , "  uint64_t capacity = 16;"
      , "  while (capacity < wanted.bits && capacity < (UINT64_C(1) << 62)) capacity *= 2;"
      , "  return pudu_make(capacity, 0);"
      , "}"
      ])
  , ("swiss_control", ["tree_find", "kernel_int"],
      [ "/* A slot's control byte. Eight live in each word of the control store; a"
      , "   word the store lacks reads as all empty. */"
      , "static unsigned pudu_swiss_control(pudu_tree_node *control, int64_t slot, const pudu_tree_ops *ops) {"
      , "  pudu_cell key;"
      , "  pudu_tree_node *found;"
      , "  key.integer = pudu_kernel_int(slot >= 0 ? slot >> 3 : -((-(slot + 1)) >> 3) - 1);"
      , "  found = pudu_tree_find(control, key, ops);"
      , "  return (unsigned)(((found == NULL ? UINT64_MAX : found->value.integer.bits) >> (((uint64_t)slot & 7) * 8)) & 0xFF);"
      , "}"
      ])
  , ("swiss_mark", ["tree_find", "tree_insert", "kernel_int", "make"],
      [ "/* The control store with one slot's byte replaced. Takes the store's reference. */"
      , "static pudu_tree_node *pudu_swiss_mark(pudu_tree_node *control, int64_t slot, unsigned byte, const pudu_tree_ops *ops) {"
      , "  pudu_cell key, value;"
      , "  pudu_tree_node *found;"
      , "  unsigned shift = (unsigned)((uint64_t)slot & 7) * 8;"
      , "  uint64_t word;"
      , "  key.integer = pudu_kernel_int(slot >= 0 ? slot >> 3 : -((-(slot + 1)) >> 3) - 1);"
      , "  found = pudu_tree_find(control, key, ops);"
      , "  word = found == NULL ? UINT64_MAX : found->value.integer.bits;"
      , "  value.integer = pudu_make((word & ~(UINT64_C(0xFF) << shift)) | ((uint64_t)byte << shift), 0);"
      , "  return pudu_tree_insert(control, key, value, 0, ops);"
      , "}"
      ])
  , ("swiss_table", ["kernel_int"],
      [ "/* The table record: capacity, count, control store, slot store. Takes the trees. */"
      , "static pudu_box *pudu_swiss_table(int64_t capacity, int64_t count, pudu_tree_node *control, pudu_tree_node *slots) {"
      , "  pudu_box *table = pudu_box_new(4), *held = pudu_box_new(1), *stored = pudu_box_new(1);"
      , "  held->fields[0].tree = control;"
      , "  stored->fields[0].tree = slots;"
      , "  table->fields[0].integer = pudu_kernel_int(capacity);"
      , "  table->fields[1].integer = pudu_kernel_int(count);"
      , "  table->fields[2].box = held;"
      , "  table->fields[3].box = stored;"
      , "  return table;"
      , "}"
      ])
  , ("swiss_holds", ["tree_find", "kernel_int"],
      [ "/* Whether the pair stored at a slot has this key. */"
      , "static int pudu_swiss_holds(pudu_tree_node *slots, int64_t slot, uint64_t key, const pudu_tree_ops *ops) {"
      , "  pudu_cell probe;"
      , "  pudu_tree_node *found;"
      , "  probe.integer = pudu_kernel_int(slot);"
      , "  found = pudu_tree_find(slots, probe, ops);"
      , "  return found != NULL && found->value.box->fields[0].integer.bits == key;"
      , "}"
      ])
  , ("swiss_find", ["swiss_hash", "swiss_control", "swiss_holds", "kernel_signed", "kernel_int", "make"],
      [ "/* The slot holding the key, or -1: linear probing from the hash's slot,"
      , "   ending at the first empty one. */"
      , "static pudu_int pudu_swiss_find(pudu_box *table, pudu_int key, const pudu_tree_ops *control_ops, const pudu_tree_ops *slot_ops) {"
      , "  int64_t capacity = pudu_kernel_signed(table->fields[0].integer.bits);"
      , "  pudu_tree_node *control = table->fields[2].box->fields[0].tree, *slots = table->fields[3].box->fields[0].tree;"
      , "  uint64_t hash = pudu_swiss_hash(key.bits), mask = (uint64_t)capacity - 1;"
      , "  unsigned mark = (unsigned)(hash >> 57) & 0x7F;"
      , "  int64_t slot = pudu_kernel_signed(hash & mask);"
      , "  if (table->fields[1].integer.bits == 0) return pudu_make(1, 1);"
      , "  for (int64_t step = 0; step < capacity; ++step) {"
      , "    unsigned held = pudu_swiss_control(control, slot, control_ops);"
      , "    if (held == 0xFF) break;"
      , "    if (held == mark && pudu_swiss_holds(slots, slot, key.bits, slot_ops)) return pudu_kernel_int(slot);"
      , "    slot = pudu_kernel_signed(((uint64_t)slot + 1) & mask);"
      , "  }"
      , "  return pudu_make(1, 1);"
      , "}"
      ])
  , ("swiss_insert", ["swiss_hash", "swiss_control", "swiss_mark", "swiss_holds", "swiss_table", "tree", "tree_retain", "tree_insert", "tree_walk", "kernel_signed", "kernel_int"],
      [ "/* The table with the pair stored under its key. Past three quarters full it"
      , "   first doubles, placing every pair again in slot order without tombstones. */"
      , "static pudu_box *pudu_swiss_insert(pudu_box *table, pudu_box *pair, const pudu_tree_ops *control_ops, const pudu_tree_ops *slot_ops) {"
      , "  int64_t capacity = pudu_kernel_signed(table->fields[0].integer.bits), count = pudu_kernel_signed(table->fields[1].integer.bits);"
      , "  pudu_tree_node *control = pudu_tree_retain(table->fields[2].box->fields[0].tree);"
      , "  pudu_tree_node *slots = pudu_tree_retain(table->fields[3].box->fields[0].tree);"
      , "  uint64_t key = pair->fields[0].integer.bits, hash = pudu_swiss_hash(key), mask;"
      , "  unsigned mark = (unsigned)(hash >> 57) & 0x7F;"
      , "  int64_t slot, tomb = 0;"
      , "  int tombed = 0;"
      , "  pudu_cell at, stored;"
      , "  if (pudu_kernel_signed(((uint64_t)count + 1) * 4) > pudu_kernel_signed((uint64_t)capacity * 3)) {"
      , "    pudu_tree_node *grown_control = NULL, *grown_slots = NULL, **nodes = pudu_tree_nodes(slots);"
      , "    size_t held = pudu_tree_size(slots);"
      , "    capacity = pudu_kernel_signed((uint64_t)capacity * 2);"
      , "    mask = (uint64_t)capacity - 1;"
      , "    for (size_t index = 0; index < held; ++index) {"
      , "      uint64_t moved = pudu_swiss_hash(nodes[index]->value.box->fields[0].integer.bits);"
      , "      slot = pudu_kernel_signed(moved & mask);"
      , "      for (int64_t step = 0; step < capacity && pudu_swiss_control(grown_control, slot, control_ops) != 0xFF; ++step)"
      , "        slot = pudu_kernel_signed(((uint64_t)slot + 1) & mask);"
      , "      grown_control = pudu_swiss_mark(grown_control, slot, (unsigned)(moved >> 57) & 0x7F, control_ops);"
      , "      at.integer = pudu_kernel_int(slot);"
      , "      grown_slots = pudu_tree_insert(grown_slots, at, slot_ops->retain_value(nodes[index]->value), 0, slot_ops);"
      , "    }"
      , "    free(nodes);"
      , "    pudu_tree_release(control, control_ops);"
      , "    pudu_tree_release(slots, slot_ops);"
      , "    control = grown_control;"
      , "    slots = grown_slots;"
      , "  }"
      , "  mask = (uint64_t)capacity - 1;"
      , "  slot = pudu_kernel_signed(hash & mask);"
      , "  for (int64_t step = 0; step < capacity; ++step) {"
      , "    unsigned held = pudu_swiss_control(control, slot, control_ops);"
      , "    if (held == 0xFF) {"
      , "      if (tombed) slot = tomb;"
      , "      control = pudu_swiss_mark(control, slot, mark, control_ops);"
      , "      count = pudu_kernel_signed((uint64_t)count + 1);"
      , "    }"
      , "    if (held == 0xFF || (held == mark && pudu_swiss_holds(slots, slot, key, slot_ops))) {"
      , "      at.integer = pudu_kernel_int(slot);"
      , "      stored.box = pudu_box_retain(pair);"
      , "      slots = pudu_tree_insert(slots, at, stored, 0, slot_ops);"
      , "      break;"
      , "    }"
      , "    if (held == 0xFE && !tombed) { tomb = slot; tombed = 1; }"
      , "    slot = pudu_kernel_signed(((uint64_t)slot + 1) & mask);"
      , "  }"
      , "  return pudu_swiss_table(capacity, count, control, slots);"
      , "}"
      ])
  , ("swiss_delete", ["swiss_hash", "swiss_control", "swiss_mark", "swiss_holds", "swiss_table", "tree_retain", "tree_remove", "kernel_signed", "kernel_int"],
      [ "/* The table without the key: its slot is emptied and marked as a tombstone. */"
      , "static pudu_box *pudu_swiss_delete(pudu_box *table, pudu_int key, const pudu_tree_ops *control_ops, const pudu_tree_ops *slot_ops) {"
      , "  int64_t capacity = pudu_kernel_signed(table->fields[0].integer.bits), count = pudu_kernel_signed(table->fields[1].integer.bits);"
      , "  pudu_tree_node *control = pudu_tree_retain(table->fields[2].box->fields[0].tree);"
      , "  pudu_tree_node *slots = pudu_tree_retain(table->fields[3].box->fields[0].tree);"
      , "  uint64_t hash = pudu_swiss_hash(key.bits), mask = (uint64_t)capacity - 1;"
      , "  unsigned mark = (unsigned)(hash >> 57) & 0x7F;"
      , "  int64_t slot = pudu_kernel_signed(hash & mask);"
      , "  for (int64_t step = 0; count != 0 && step < capacity; ++step) {"
      , "    unsigned held = pudu_swiss_control(control, slot, control_ops);"
      , "    if (held == 0xFF) break;"
      , "    if (held == mark && pudu_swiss_holds(slots, slot, key.bits, slot_ops)) {"
      , "      pudu_cell at;"
      , "      at.integer = pudu_kernel_int(slot);"
      , "      control = pudu_swiss_mark(control, slot, 0xFE, control_ops);"
      , "      slots = pudu_tree_remove(slots, at, slot_ops);"
      , "      count -= 1;"
      , "      break;"
      , "    }"
      , "    slot = pudu_kernel_signed(((uint64_t)slot + 1) & mask);"
      , "  }"
      , "  return pudu_swiss_table(capacity, count, control, slots);"
      , "}"
      ])
  ]
